"""Records of the ledger formats v1 and v2, read the way reporting/ledger.go reads them."""

import re

DIGITS = re.compile(r"[0-9]+")
HEADER = "# ledger v2"
# bufio.Scanner keeps a line and its line feed in a buffer of at most 64 KiB;
# a longer line ends the scan, and the lines after it are never scanned.
MAX_LINE_BYTES = 64 * 1024 - 1
UINT64_MAX = (1 << 64) - 1
INT64_MIN = -(1 << 63)
INT64_MAX = (1 << 63) - 1


def size(text):
    return len(text.encode("utf-8", "surrogatepass"))


def raw_lines(text):
    """(number, raw line) for every line bufio.Scanner yields, before its CR drop."""
    pieces = text.split("\n")
    if pieces[-1] == "":
        pieces.pop()
    lines = []
    for number, piece in enumerate(pieces, 1):
        if size(piece) > MAX_LINE_BYTES:
            break
        lines.append((number, piece))
    return lines


def complete(text):
    """Whether bufio.Scanner reads all of text without ErrTooLong."""
    pieces = text.split("\n")
    if pieces[-1] == "":
        pieces.pop()
    return all(size(piece) <= MAX_LINE_BYTES for piece in pieces)


def drop_cr(line):
    return line[:-1] if line.endswith("\r") else line


def skipped(line):
    return line == "" or line.startswith("#")


def export_lines(text):
    """(number, line) for every line of an export that ReadPart does not skip."""
    lines = []
    for number, raw in raw_lines(text):
        line = drop_cr(raw)
        if not skipped(line):
            lines.append((number, line))
    return lines


def parse_uint(text):
    if not DIGITS.fullmatch(text):
        raise ValueError(text)
    value = int(text)
    if value > UINT64_MAX:
        raise ValueError(text)
    return value


def parse_int(text):
    negative = text.startswith("-")
    digits = text[1:] if text[:1] in ("+", "-") else text
    value = parse_uint(digits)
    value = -value if negative else value
    if not INT64_MIN <= value <= INT64_MAX:
        raise ValueError(text)
    return value


def decode_v1(line):
    """ParseRecord: (id, day, account, amount, memo); ValueError when it rejects line."""
    fields = line.split("|", 4)
    if len(fields) != 5:
        raise ValueError(line)
    return (parse_uint(fields[0]), fields[1], fields[2], parse_int(fields[3]), fields[4])


def encode_v2(record, part, number):
    record_id, day, account, amount, memo = record
    return f"{record_id}|{day}|{account}|{amount}|{memo}|src={part}:{number}"


def split(part, lines):
    """The v2 text of an export's lines and its quarantine lines."""
    records, rejected = [], []
    for number, line in lines:
        try:
            record = decode_v1(line)
        except ValueError:
            rejected.append(f"{part}:{number}:{line}\n")
        else:
            records.append(encode_v2(record, part, number) + "\n")
    return HEADER + "\n" + "".join(records), rejected


def readable(text):
    """Whether ReadPart reads text without an error."""
    if not complete(text):
        return False
    for _, line in export_lines(text):
        try:
            decode_v1(line)
        except ValueError:
            return False
    return True

"""Conversion of ledger exports to format v2.

Every step can be stopped. A part's lines are first kept in a journal, a
complete JSON text with an end line, so that no later step loses them. A part
is published by writing its v2 file under a name the index does not name yet
and only then appending its index line, so the reporting service only ever
reads complete files. The quarantine is rebuilt from the journals, and an
export is deleted only once its part is published.
"""

import json
import sys

import codec
from storage import Missing

INDEX = "v2/index"
QUARANTINE = "quarantine"
JOURNAL = "migrate-journal/"
END = "\nEND\n"


def log(message):
    print(f"migrate: {message}", file=sys.stderr)


def read(store, name):
    try:
        return store.read(name)
    except Missing:
        return None


def index_entries(store):
    """(part, file) per index line, as Published reads them."""
    entries = []
    for _, raw in codec.raw_lines(read(store, INDEX) or ""):
        part, sep, file = codec.drop_cr(raw).partition(" ")
        if sep:
            entries.append((part, file))
    return entries


def load_journal(store, part):
    text = read(store, JOURNAL + part)
    if text is None or not text.endswith(END):
        return None
    try:
        data = json.loads(text[: -len(END)])
    except ValueError:
        return None
    if not isinstance(data, dict) or data.get("part") != part:
        return None
    return [(number, line) for number, line in data["lines"]]


def journal_text(part, lines):
    body = json.dumps({"part": part, "lines": [list(item) for item in lines]})
    return body + END


def reconstruct(store, part, file, quarantine):
    """The lines of an export an earlier run published and deleted.

    The published file holds the line of every record it accepted (with its
    line number in src=) and the quarantine every line it rejected.
    """
    found = {}
    for piece in (read(store, file) or "").split("\n") if file else []:
        head, sep, src = piece.rpartition("|src=")
        owner, colon, number = src.partition(":")
        if sep and colon and owner == part and codec.DIGITS.fullmatch(number):
            found[int(number)] = head
    for piece in quarantine.split("\n"):
        owner, sep, rest = piece.partition(":")
        number, colon, text = rest.partition(":")
        if sep and colon and owner == part and codec.DIGITS.fullmatch(number):
            found.setdefault(int(number), text)
    lines = []
    for number in sorted(found):
        raw = found[number]
        if codec.size(raw) > codec.MAX_LINE_BYTES:
            break
        line = codec.drop_cr(raw)
        if not codec.skipped(line):
            lines.append((number, line))
    return lines


def free_name(part, referenced):
    name, attempt = f"v2/{part}", 0
    while name in referenced:
        attempt += 1
        name = f"v2/{part}.{attempt}"
    return name


def run(store):
    exports = [name.removeprefix("v1/") for name in store.names("v1/")]
    journaled = [name.removeprefix(JOURNAL) for name in store.names(JOURNAL)]
    entries = index_entries(store)
    effective = dict(entries)
    referenced = {file for _, file in entries}
    quarantine = read(store, QUARANTINE) or ""
    parts = sorted(set(exports) | set(effective) | set(journaled))

    def urgency(part):
        if part not in effective:
            return 2
        text = read(store, effective[part])
        return 0 if text is None or not codec.readable(text) else 1

    parts.sort(key=urgency)
    log(f"start: {len(exports)} exports to convert, {len(parts)} parts")
    rejected = {}
    for part in parts:
        lines = load_journal(store, part)
        if lines is None:
            if part in exports:
                lines = codec.export_lines(store.read(f"v1/{part}"))
            else:
                lines = reconstruct(store, part, effective.get(part), quarantine)
            store.write(JOURNAL + part, journal_text(part, lines))
        content, rejected[part] = codec.split(part, lines)
        current = effective.get(part)
        if current is None or read(store, current) != content:
            name = free_name(part, referenced)
            if read(store, name) != content:
                store.write(name, content)
            store.append(INDEX, f"{part} {name}\n")
            referenced.add(name)
            effective[part] = name
            log(f"{part} published as {name} ({len(rejected[part])} quarantined)")
    wanted = "".join(line for part in sorted(rejected) for line in rejected[part])
    current = read(store, QUARANTINE)
    if wanted and current != wanted:
        store.write(QUARANTINE, wanted)
    elif not wanted and current is not None:
        store.delete(QUARANTINE)
    for part in exports:
        store.delete(f"v1/{part}")
    log("done")
